WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_burst FROM payments), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT order_id, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN status = 'FAILED' THEN 1 END), 0), 2) AS amount_per_failed, SUM(CASE WHEN method = 'card' THEN burst_id ELSE 0 END) AS card_burst_id, SIZE(COLLECT_SET(status)) AS num_status, COUNT(CASE WHEN status = 'REFUNDED' THEN 1 END) AS refunded_count, ROUND(SUM(burst_id) / NULLIF(COUNT(CASE WHEN status = 'REFUNDED' THEN 1 END), 0), 2) AS burst_id_per_refunded, GROUPING_ID() AS grouping_level FROM sessionized GROUP BY CUBE (order_id) ORDER BY order_id NULLS LAST;
